namespace LittleNotebook {public partial class MainWindow {
 public async void RunNavigationChecks(){int count=0;string phase="setup",report=System.IO.Path.Combine(baseDir,"../test-output/navigation.txt");Action<bool,string> check=(ok,message)=>{count++;if(!ok)throw new Exception(message);};File.WriteAllText(report,"RUNNING");try{
  timer.Stop();audio.Dispose();Profile=new Profile{Name="Maya"};Profile.Settings.Music=Profile.Settings.Sound=false;audio=new AudioSystem(Profile.Settings);page="notebook";Build();UpdateLayout();
  phase="pan and modifiers";SetNotebookZoom(2);notebookScroll.UpdateLayout();ConfigureNotebookTool("pen");int strokes=notebookInk.Strokes.Count,undos=notebookUndo.Count;notebookScroll.ScrollToHorizontalOffset(250);notebookScroll.ScrollToVerticalOffset(200);notebookScroll.UpdateLayout();double x=notebookScroll.HorizontalOffset,y=notebookScroll.VerticalOffset;notebookPan.Begin(new Point(200,150),false);check(notebookPan.Active&&notebookScroll.Cursor==PanCursor.Closed&&notebookScroll.ForceCursor,"Pan cursor missing");notebookPan.Move(new Point(150,100));notebookScroll.UpdateLayout();check(notebookScroll.HorizontalOffset>x+40&&notebookScroll.VerticalOffset>y+40,"Pan does not move both axes");NotebookPointerMove(new Point(220,120));check(notebookGhost.Children.Count==0,"Drawing cursor remains during pan");notebookPan.End();check(!notebookPan.Active&&!notebookScroll.ForceCursor&&notebookInk.Strokes.Count==strokes&&notebookUndo.Count==undos,"Pan changed drawing or failed to release");
  check(NotebookWheelZoom(ModifierKeys.Alt)&&NotebookWheelZoom(ModifierKeys.Control)&&!NotebookWheelZoom(ModifierKeys.None),"Wheel modifier rules incorrect");foreach(Key alt in new[]{Key.LeftAlt,Key.RightAlt}){check(NotebookAltKey(alt,notebookInk)&&!NotebookAltKey(alt,new TextBox()),"Alt suppression interferes with typing");foreach(var routed in new[]{Keyboard.PreviewKeyDownEvent,Keyboard.PreviewKeyUpEvent}){var e=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(this),0,alt){RoutedEvent=routed};notebookInk.RaiseEvent(e);check(e.Handled,"Alt falls through to menu mode");}NotebookPointerMove(new Point(250,140));check(notebookGhost.Children.Count==1,"Pointer did not follow after Alt");}
  phase="cursor geometry";foreach(string style in new[]{"round","fine","chisel","soft"}){Profile.Settings.NotebookPen=style;ConfigureNotebookTool("pen");NotebookPointerMove(new Point(240,120));check(style=="chisel"?notebookTip is Rectangle:notebookTip is Ellipse,"Pen tip shape mismatch: "+style);check(Math.Abs(notebookTip.Height-Math.Max(2,notebookInk.DefaultDrawingAttributes.Height))<.01,"Cursor ignores nib height");if(style=="chisel")check(notebookTip.RenderTransform.Value==notebookInk.DefaultDrawingAttributes.StylusTipTransform,"Chisel cursor ignores nib rotation");}SetNotebookZoom(1);notebookScroll.ScrollToHorizontalOffset(0);notebookScroll.ScrollToVerticalOffset(0);notebookScroll.UpdateLayout();notebookSize=14;Profile.Settings.NotebookPen="chisel";ConfigureNotebookTool("pen");NotebookPointerMove(new Point(240,120));Capture("navigation-chisel-cursor");notebookSize=3;ConfigureNotebookTool("fill");NotebookPointerMove(new Point(140,80));check(Canvas.GetLeft(notebookFillPointer)==140&&Canvas.GetTop(notebookFillPointer)==80,"Fill cursor hotspot is not its top-left tip");Capture("navigation-fill-cursor");
  phase="artwork fitting";ClearNotebookPage();CurrentNotebookPage.Template="anime-naruto";CurrentNotebookPage.TraceVisible=true;CurrentNotebookPage.TraceWidth=CurrentNotebookPage.TraceHeight=400;CurrentNotebookPage.Height=450;var original=Sketch.Asset("tracings/naruto.png");var outline=PhotoTracing.Extract(original,45,p.Ink);double scale=400.0/Math.Max(original.PixelWidth,original.PixelHeight);outline.Transform(new Matrix(scale,0,0,scale,270+(400-original.PixelWidth*scale)/2,35+(400-original.PixelHeight*scale)/2),false);notebookInk.Strokes=outline;FlushNotebook();ResizeNotebookSurface();RefreshNotebookGuide();
  foreach(string theme in new[]{"matcha","sky","rose","lavender","night"})foreach(string lang in new[]{"en","ar"}){Profile.Settings.Theme=theme;Profile.Settings.Language=lang;Profile.Settings.Paper=PaperDesign.ForTheme(theme);Build();CompareNotebookTrace();UpdateLayout();check(comparisonBounds.Width<500&&comparisonBounds.Height<450,"Comparison fits paper rather than artwork");check(comparisonFit>.5,"Comparison starts too small");check(comparisonImages.All(i=>Math.Abs(i.Width-comparisonBounds.Width)<.01),"Comparison sides use different coordinate crops");Capture("comparison-"+theme+"-"+lang);double fit=comparisonFit;ZoomComparison(fit*2);check(comparisonZoom==fit*2&&comparisonImages.All(i=>i.LayoutTransform.Value.M11==comparisonZoom),"Linked zoom failed");comparisonScroll[0].ScrollToVerticalOffset(70);comparisonScroll[0].UpdateLayout();await Task.Delay(15);comparisonScroll[1].UpdateLayout();check(Math.Abs(comparisonScroll[0].VerticalOffset-comparisonScroll[1].VerticalOffset)<1,"Comparison pan not linked");ZoomComparison(fit);CloseModal();check(comparisonImages==null,"Comparison bitmaps retained after close");}
  Profile.Settings.Language="en";foreach(double size in new[]{35.0,120.0,820.0}){CurrentNotebookPage.Template="flower";CurrentNotebookPage.TraceWidth=CurrentNotebookPage.TraceHeight=size;CurrentNotebookPage.Height=Math.Max(414,size+70);notebookInk.Strokes.Clear();FlushNotebook();ResizeNotebookSurface();CompareNotebookTrace();UpdateLayout();check(comparisonBounds.Width*comparisonFit<=271&&comparisonBounds.Height*comparisonFit<=425,"Fit clips a differently-sized tracing");Capture("comparison-size-"+(int)size);CloseModal();}
  CurrentNotebookPage.TraceInk=EncodeInk(new StrokeCollection{new Stroke(new StylusPointCollection(new[]{new StylusPoint(0,0),new StylusPoint(600,900)}))});CurrentNotebookPage.Template="imported";CurrentNotebookPage.TraceWidth=600;CurrentNotebookPage.TraceHeight=900;CurrentNotebookPage.Height=12000;FlushNotebook();ResizeNotebookSurface();CompareNotebookTrace();check(comparisonBounds.Height<1000,"Extended blank paper dilutes preview fit");CloseModal();
  phase="flexible pour";var puzzle=new ExtraPuzzle("pour",1,5);puzzle.Tubes=new List<List<int>>{new List<int>{0,0},new List<int>{1},new List<int>{2,2,2,2},new List<int>(),new List<int>()};check(puzzle.Input(0)&&puzzle.Input(1)&&puzzle.Tubes[1].SequenceEqual(new[]{1,0,0}),"Different colours cannot be poured together");check(puzzle.Undo()&&puzzle.Selected==-1&&puzzle.Tubes[0].Count==2&&puzzle.Tubes[1].SequenceEqual(new[]{1}),"Mixed pour undo incorrect");puzzle.Input(0);puzzle.Input(2);check(puzzle.Message=="blocked"&&puzzle.Tubes[2].Count==4,"Full tube overflow allowed");puzzle.Input(0);check(puzzle.Selected==-1&&puzzle.Feedback==0,"Deselect replays pour");
  phase="completion feedback";audio.Dispose();Profile.Settings.Sound=true;audio=new AudioSystem(Profile.Settings,true);var requests=new List<string>();audio.PlaybackRequested+=requests.Add;StartMiniGame("pour");await Task.Delay(100);check(requests.Count==0,"Starting pour plays a completion cue");mini.Extra.Tubes=new List<List<int>>{new List<int>{0,0,0},new List<int>{0},new List<int>{1,1,1,1},new List<int>{2},new List<int>{2,2,2}};MiniPress(1);MiniPress(0);check(mini.Extra.IsTubeComplete(0)&&mini.Extra.NewCompletedTube==0&&requests.Count(r=>r=="cue-pulse")==1,"Completed tube does not play one positive cue");MiniPress(3);MiniPress(3);check(requests.Count(r=>r=="cue-pulse")==1,"Deselect replays completion cue");mini.Extra.Feedback=0;miniSurface.InvalidateVisual();Capture("pour-completed-tube");UndoExtra();check(!mini.Extra.IsTubeComplete(0)&&mini.Extra.NewCompletedTube==-1,"Undo keeps completion state");BackToMiniGames();check(Diagnostics.ErrorCount==0,"Native navigation errors logged");
  File.WriteAllText(report,"PASS: "+count+" focused checks; middle-drag pans both axes without ink/history changes; Alt down/up consumed without locking pointer; Ctrl/Alt wheel rules; nib-matched rotated cursor and precise fill hotspot; linked artwork-cropped comparison zoom/pan in all five themes and both languages and varied sizes; mixed-colour pour, capacity, undo/deselect and one muted native completion cue. Native screenshots captured. No desktop interaction.");
 }catch(Exception ex){File.WriteAllText(report,"FAIL in "+phase+" after "+count+": "+ex);Environment.ExitCode=1;}finally{closing=true;Close();}}
